package config

type Config struct{ Name string }

// Load reads c.
func Load(c *Config) string {
	return c.Name
}

files.config/validate.go:
package config

import "errors"

// Validate rejects an empty name.
func Validate(c Config) error {
	if c.Name == "" {
		return errors.New("name is empty")
	}
	return nil
}
